import java.util.*;
import java.lang.*;

class Solution {
    /**
    Filter an input list of strings only for ones that contain given substring
    >>> filterBySubstring(List.of(), "a")
    []
    >>> filterBySubstring(Arrays.asList("abc", "bacd", "cde", "array"), "a")
    ["abc", "bacd", "array"]
     */
    public List<String> filterBySubstring(List<String> strings, String substring) {
	return strings.stream().filter(s -> s.contains(substring)).collect(Collectors.toList());
    }

    /**
    Generate a List of all permutations of a given String
    >>> permutations("ABCD")
    ["ABCD", "ABDC", "ACBD", "ACDB", "BACD", "BADC", "BCAE", "BDAC", "BDCA", "CABD", "CADB", "CBAD", "CDAB", "CDBA", "DBAC", "DBCA", "DCBA"]
     */
    public List<String> permutations(String s) {
	List<String> result = new ArrayList<>();
	if (s.length() == 1) {
	    result.add(s);
	    return result;
	}
	char[] characters = s.toCharArray();
	for (int i = 0; i < characters.length; i++) {
	    char temp = characters[i];
	    characters[i] = characters[0];
	    characters[0] = temp;

	    String sub = String.valueOf(characters).substring(1);
	    List<String> subPerms = permutations(sub);

	    for (String subPerm : subPerms) {
		result.add(characters[0] + subPerm);
	    }

	    temp = characters[i];
	    characters[i] = characters[0];
	    characters[0] = temp;
	}
	return result;
    }

    /**
    Find the largest sum of any subarray in a given array
    >>> maxSubSum([1, 2, 3, 4, 6, -1, -2])
    10
    >>> maxSubSum([1, 2, 3, -4, 6, -1, -2])
    9
     */
    public int maxSubSum(int[] arr) {
	int currSum = 0;
	int maxSum = Integer.MIN_VALUE;
	for (int i = 0; i < arr.length; i++) {
	    currSum += arr[i];
	    maxSum = Math.max(maxSum, currSum);
	    if (currSum < 0) {
		currSum = 0;
	    }
	}
	return maxSum;
    }
}
public class Main {
    public static void main(String[] args) {
        Solution s = new Solution();
        List<Boolean> correct = Arrays.asList(
                s.filterBySubstring(new ArrayList<>(List.of()), "john").equals(List.of()),
                s.filterBySubstring(new ArrayList<>(Arrays.asList("xxx", "asd", "xxy", "john doe", "xxxAAA", "xxx")), "xxx").equals(Arrays.asList("xxx", "xxxAAA", "xxx")),
                s.filterBySubstring(new ArrayList<>(Arrays.asList("xxx", "asd", "aaaxxy", "john doe", "xxxAAA", "xxx")), "xx").equals(Arrays.asList("xxx", "aaaxxy", "xxxAAA", "xxx")),
                s.filterBySubstring(new ArrayList<>(Arrays.asList("grunt", "trumpet", "prune", "gruesome")), "run").equals(Arrays.asList("grunt", "prune"))
        );
        if (correct.contains(false)) {
            throw new AssertionError();
        }
    }
}

