    True
    >>> isStringInIncreasingOrder('ab')
    True
    >>> isStringInIncreasingOrder('a')
    True
    >>> isStringInIncreasingOrder('abcde')
    True
    >>> isStringInIncreasingOrder('acb')
    False
    >>> isStringInIncreasingOrder('bac')
    False
     */
    public boolean isStringInIncreasingOrder(String s) {
        char[] characters = s.toCharArray();
        for (int i = 1; i < characters.length; i++) {
            if (characters[i-1] > characters[i]) {
                return false;
            }
        }
        return true;
    }

    /**
