    public int longestIncreasingSubsequenceLength(List<Integer> numbers) {
        int max = 1;
        int currentLength = 1;
        for (int i = 1; i < numbers.size(); i++) {
            if (numbers.get(i-1) < numbers.get(i)) {
                currentLength += 1;
            } else {
                max = Math.max(max, currentLength);
                currentLength = 1;
            }
        }
        max = Math.max(max, currentLength);
        return max;
    }
}
