class Solution {
    /**
    From a list of integers, remove all elements that occur more than once.
    Keep order of elements left the same as in the input.
    >>> removeDuplicates(Array.asList(1, 2, 3, 2, 4))
    [1, 3, 4]
     */
    public List<Integer> removeDuplicates(List<Integer> numbers) {
	return numbers.stream().distinct().collect(Collectors.toList());
    }

    /**
    Given a list of words, find the shortest word in the list.
    Assume no word is longer than 20 characters. Assume all words will only use valid ASCII characters.
    >>> findShortestWord(Array.asList("apple", "banana", "cherry"))
    "apple"
     */
    public String findShortestWord(List<String> words) {
	return words.stream().min(Comparator.comparingInt(String::length)).get();
    }

    /**
    Given a list of words, return a list of those words, except for the word "banana" and its variants.
    The returned list must maintain the order of words in the original list.
    >>> removeBanana(Array.asList("apple", "banana", "cherry", "orange", "banana"))
    ["apple", "cherry", "orange", "banana"]
     */
    public List<String> removeBanana(List<String> words) {
	return words.stream().filter(w ->!w.toLowerCase().startsWith("banana")).collect(Collectors.toList());
