    Determine if a string is a palindrome
    >>> isPalindrome("radar")
    True
    >>> isPalindrome("qwert")
    False
    >>> isPalindrome("rotor")
    True
     */
    public boolean isPalindrome(String s) {
	if (s.length() <= 1) {
	    return true;
	}

	int left = 0;
	int right = s.length() - 1;

	while (left < right) {
	    if (s.charAt(left)!= s.charAt(right)) {
		return false;
	    }
	    left++;
	    right--;
	}
	return true;
    }

    /**
    Determine if a string is an anagram of another string
    >>> isAnagram("anagram", "nagaram")
    True
    >>> isAnagram("rat", "car")
    False
     */
    public boolean isAnagram(String s, String t) {
	if (s.length()!= t.length()) {
	    return false;
	}

	Map<Character, Integer> characters = new HashMap<>();

	// Increase count of chars at that position in map
	// for characters in first string
	for (char c : s.toCharArray()) {
	    characters.put(c, characters.getOrDefault(c, 0) + 1);
	}

	// Decrease count of chars at that position in map
	// for characters in second string
	for (char c : t.toCharArray()) {
	    characters.put(c, characters.getOrDefault(c, 0) - 1);
	}

	// If any count is non-zero, then not anagram
	for (Map.Entry<Character, Integer> entry : characters.entrySet()) {
	    if (entry.getValue()!= 0) {
		return false;
	    }
	}
	return true;
    }
