    >>> findZero(Arrays.asList(-6, 11, -6, 1)) // (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
     */
    public double findZero(List<Double> xs) {
	assert xs.size() % 2 == 0;
	double a = xs.get(xs.size() - 2) / xs.get(xs.size() - 1); // -b/a
	double b = xs.get(xs.size() - 4) / xs.get(xs.size() - 1); // c/a
