import java.util.*;
import java.lang.*;

class Solution {
    /**
    Change numerical base of input number x to base.
    return string representation after the conversion.
    base numbers are less than 10.
    >>> changeBase(8, 3)
    "22"
    >>> changeBase(8, 2)
    "1000"
    >>> changeBase(7, 2)
    "111"
     */
    public String changeBase(int x, int base) {
	if (x<0 || base<2 || base>10) {
	    throw new IllegalArgumentException();
	}
	boolean isNegative = x<0;
	if (isNegative) {
	    x = -x;
	}
	StringBuilder sb = new StringBuilder();
	// quotient and remainder
	int q, r;
	while (x>0) {
	    // x = q*base + r
	    q = x/base;
	    r = x%base;
	    x = q;
	    sb.append(r);
	}
	if (isNegative) {
	    sb.append("-");
	}
	// reverse string and return
	sb.reverse();
	return sb.toString();
    }

    /**
    Change numerical base of input number x to base.
    return string representation after the conversion.
    base numbers can be greater than 10.
    >>> changeBaseWithLargeBase(8, 13)
    "31"
    >>> changeBaseWithLargeBase(10, 17)
    "10"
    >>> changeBaseWithLargeBase(7, 2)
    "111"
     */
    public String changeBaseWithLargeBase(int x, int base) {
	if (x<0 || base<2) {
	    throw new IllegalArgumentException();
	}
	boolean isNegative = x<0;
	if (isNegative) {
	    x = -x;
	}
	StringBuilder sb = new StringBuilder();
	// quotient and remainder
	int q, r;
	while (x>0) {
	    // x = q*base + r
	    q = x/base;
	    r = x%base;
	    x = q;

	    char digit = (char)(r + '0');
	    // if r is greater than 9, add 'A' to it
	    if (r > 9) {
		digit = (char)(r + 'A' - 10);
	    }
	    sb.append(digit);
	}
	if (isNegative) {
	    sb.append("-");
	}
	// reverse string and return
	sb.reverse();
	return sb.toString();
    }

    }
public class Main {
    public static void main(String[] args) {
        Solution s = new Solution();
        List<Boolean> correct = Arrays.asList(
                Objects.equals(s.changeBase(8, 3), "22"),
                Objects.equals(s.changeBase(9, 3), "100"),
                Objects.equals(s.changeBase(234, 2), "11101010"),
                Objects.equals(s.changeBase(16, 2), "10000"),
                Objects.equals(s.changeBase(8, 2), "1000"),
                Objects.equals(s.changeBase(7, 2), "111")
        );
        if (correct.contains(false)) {
            throw new AssertionError();
        }
        for (int x = 2; x < 8; x++) {
            if (!Objects.equals(s.changeBase(x, x + 1), String.valueOf(x))) {
                throw new AssertionError();
            }
        }
    }
}

