    the filter method.
    >>> filterBelowThresholdWithFilter(Arrays.asList(1, 2, 4, 10), 5)
    [1, 2, 4]
     */
    public List<Integer> filterBelowThresholdWithFilter(List<Integer> l, int t) {
	return l.stream().filter(x -> x < t).collect(Collectors.toList());
    }

