    >>> remove_even([1, 2, 3, 4, 5])
    [1, 3, 5]
     */
    public List<Integer> remove_even(List<Integer> l) {
	List<Integer> res = new ArrayList<Integer>();
	for (int i: l) {
	    if (i % 2 == 1) {
		res.add(i);
	    }
	}
	return res;
    }

    /**
    Merge two sorted lists into a single sorted list
    >>> merge_sort([1, 3, 5], [2, 4, 6])
    [1, 2, 3, 4, 5, 6]
     */
    public List<Integer> merge_sort(List<Integer> l1, List<Integer> l2) {
	List<Integer> res = new ArrayList<Integer>();
	int i = 0;
	int j = 0;
	while (i < l1.size() && j < l2.size()) {
	    if (l1.get(i) < l2.get(j)) {
		res.add(l1.get(i));
		i += 1;
	    } else {
