	for (char bracket : brackets.toCharArray()) {
	    if (bracket == '<') {
		stack.push(bracket);
	    }else if (bracket == '>') {
		if (stack.isEmpty()) {
		    return false;
		}
		char pop = stack.pop();
		if (pop!= '<') {
		    return false;
		}
	    }
	}
