        int maxFactor = factor;

        while (factor <= Math.sqrt(n)) {
            if (n % factor == 0) {
                maxFactor = factor;
                while (n % factor == 0) {
                    n /= factor;
                }
            }
            factor += 1;
        }
        if (n > 1) {
            maxFactor = n;
        }

        return maxFactor;
