class Solution {
    /**
    You are given two positive integers n and m, and your task is to compute the
    average of the integers from n through m (including n and m).
    Round the answer to the nearest integer and convert that to binary.
    If n is greater than m, return -1.
    Example:
    roundedAvg(1, 5) => "11"
    roundedAvg(7, 5) => -1
    roundedAvg(10, 20) => "1111"
    roundedAvg(20, 33) => "11011"
     */
    public Object roundedAvg(int n, int m) {
	// edge case: n > m
	if (n > m) {
	    return -1;
	}
	// sum n through m
	int sum = 0;
	for (int i = n; i <= m; i++) {
	    sum += i;
	}
	// average of n through m
	double avg = (double)sum / (m - n + 1);
	// round the average to nearest integer
	int rounded = (int)Math.round(avg);
	// convert to binary
	return Integer.toBinaryString(rounded);
    }

    /**
    You are given an array of integers.
    All numbers are equal except for one, which is larger than all of them.
    Your task is to find that number.
    The array will always contain at least 3 numbers.
    The array will never contain two equal numbers.
    Example:
    findUniq([1, 5, 5, 10, 25]) => 25
    findUniq([1, 5, 10, 25]) => 10
    findUniq([1, 5, 5, 10, 10]) => 1
     */
    public Object findUniq(int[] arr) {
	// sort the array
	Arrays.sort(arr);
	// loop through array
	// if current element is not equal to previous element
	// and not equal to next element, then that number is unique
	for (int i = 0; i < arr.length; i++) {
	    if (i == 0 && arr[i]!= arr[i + 1]) {
		return arr[i];
	    } else if (i == arr.length - 1 && arr[i]!= arr[i - 1]) {
		return arr[i];
	    } else if (arr[i]!= arr[i - 1] && arr[i]!= arr[i + 1]) {
		return arr[i];
	    }
	}
	return null;
    }
}
