class Solution {
    /**
    Given a list of strings, where each string consists of only digits, return a list.
    Each element i of the output should be "the number of odd elements in the
    string i of the input." where all the i's should be replaced by the number
    of odd digits in the i"th string of the input.

    >>> oddCount(Arrays.asList("1234567"))
    ["the number of odd elements 4n the str4ng 4 of the 4nput."]
    >>> oddCount(Arrays.asList("3","11111111"))
    ["the number of odd elements 1n the str1ng 1 of the 1nput.",
     "the number of odd elements 8n the str8ng 8 of the 8nput."]
     */
    public List<String> oddCount(List<String> lst) {
	// Write your code here.
        List<String> res = new ArrayList<>();
        for (String s : lst) {
            int odd = 0;
            for (int i = 0; i < s.length(); i++) {
                if ((s.charAt(i) - '0') % 2 == 1) {
                    odd++;
                }
            }
            String newS = s.replace(s, "the number of odd elements " + odd + "n the str" + odd + "ng " + odd + " of the " + odd + "nput");
            res.add(newS);
        }
        return res;
    }

    /**
    A binary tree is said to be balanced if the difference between the heights of
    any two leaf nodes is no greater than 1. Write a function to determine if a
    binary tree is balanced.

    >>> isBalanced(Node(1,Node(2,Node(4),None),Node(3,None,Node(5))))
    True
    >>> isBalanced(Node(1,Node(2,Node(4),None),Node(3,None,Node(6))))
    False
    >>> isBalanced(Node(1,None,Node(2,None,Node(3))))
    True
     */
    public static class Node {
        int val;
        Node left;
        Node right;
        Node(int val) {
            this.val = val;
        }
        Node(int val, Node left, Node right) {
            this.val = val;
            this.left = left;
            this.right = right;
        }
    }

    public boolean isBalanced(Node root) {
	// Write your code here.
        if (root == null) {
            return true;
        }
        return (Math.abs(height(root.left) - height(root.right)) <= 1) && isBalanced(root.left) && isBalanced(root.right);
    }

    public int height(Node root) {
        if (root == null) {
            return -1;
        }
        return Math.max(height(root.left), height(root.right)) + 1;
    }
}
