import java.util.*;
import java.lang.*;

class Solution {
    /**
    You are given a list of two strings, both strings consist of open
    parentheses "(" or close parentheses ")" only.
    Your job is to check if it is possible to concatenate the two strings in
    some order, that the resulting string will be good.
    A string S is considered to be good if and only if all parentheses in S
    are balanced. For example: the string "(())()" is good, while the string
    "())" is not.
    Return "Yes" if there"s a way to make a good string, and return "No" otherwise.

    Examples:
    matchParens(Arrays.asList("()(", ")")) == "Yes"
    matchParens(Arrays.asList(")", ")")) == "No"
     */
    public String matchParens(List<String> lst) {
	if (lst.size()!= 2) return "No";
	char[] openChars = {'(', '{', '['};
	char[] closeChars = {')', '}', ']'};
	Map<Character, Integer> openCounts = new HashMap<>();
	Map<Character, Integer> closeCounts = new HashMap<>();
	for (char c : openChars) openCounts.put(c, 0);
	for (char c : closeChars) closeCounts.put(c, 0);
	for (char c : lst.get(0).toCharArray()) {
	    if (openCounts.containsKey(c)) openCounts.put(c, openCounts.get(c) + 1);
	    else if (closeCounts.containsKey(c)) closeCounts.put(c, closeCounts.get(c) + 1);
	}
	for (char c : lst.get(1).toCharArray()) {
	    if (closeCounts.containsKey(c)) closeCounts.put(c, closeCounts.get(c) + 1);
	    else if (openCounts.containsKey(c)) openCounts.put(c, openCounts.get(c) + 1);
	}
	for (char c : openChars) {
	    if (openCounts.get(c)!= closeCounts.get(c)) return "No";
	}
	return "Yes";
    }
}

