	for (char c : openChars) openCounts.put(c, 0);
	for (char c : closeChars) closeCounts.put(c, 0);
	for (char c : lst.get(0).toCharArray()) {
	    if (openCounts.containsKey(c)) openCounts.put(c, openCounts.get(c) + 1);
	    else if (closeCounts.containsKey(c)) closeCounts.put(c, closeCounts.get(c) + 1);
	}
	for (char c : lst.get(1).toCharArray()) {
	    if (closeCounts.containsKey(c)) closeCounts.put(c, closeCounts.get(c) + 1);
	    else if (openCounts.containsKey(c)) openCounts.put(c, openCounts.get(c) + 1);
	}
	for (char c : openChars) {
	    if (openCounts.get(c)!= closeCounts.get(c)) return "No";
	}
	return "Yes";
    }
