    Example:
    >>> prodSigns(Arrays.asList(1, 2, 2, -4)) == -9
    >>> prodSigns(Arrays.asList(0, 1)) == 0
    >>> prodSigns(Arrays.asList()) == None
     */
    public Optional<Integer> prodSigns(List<Integer> arr) {
	if (arr.isEmpty()) return Optional.empty();

	int res = 1;
	boolean hasZero = false;
	for (int el: arr) {
	    if (el == 0) {
		hasZero = true;
		break;
	    }
	    res *= Math.abs(el);
	}
	if (hasZero) return Optional.of(0);

	return Optional.of(res * negCount(arr));
    }

    private int negCount(List<Integer> arr) {
	int cnt = 0;
	for (int el: arr) {
	    if (el < 0) cnt++;
	}
	return cnt % 2 == 0? 1 : -1;
    }

    }
