    If the input is null, return an empty list.
    The names in the list will only contain lowercase letters a-z.

    >>> getNamesStartingWith("st", ["step", "stop", "steven", "start"]) == ["step", "stop", "start"]
     */
    public List<String> getNamesStartingWith(String str, List<String> names) {
	List<String> result = new ArrayList<>();
	if(str == null) return result;
	for(String name : names)
	    if(name.startsWith(str)) result.add(name);
	return result;
    }

    /**
     * Given an array of integers, return the index of the first occurrence of a value in the array.
     * If the array does not contain the value, return -1.
     *
     * >>> indexOf([1, 2, 3, 4], 3) == 2
     */
    public static int indexOf(int[] arr, int x) {
	if(arr.length == 0) return -1;
	for(int i = 0; i < arr.length; i++)
	    if(arr[i] == x) return i;
	return -1;
    }
}
public class Main {
    public static void main(String[] args) throws NoSuchAlgorithmException {
        Solution s = new Solution();
